int tipc_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[TIPC_NLA_MAX + 1];
    int err;

    if (!attrs[TIPC_NLA_LINK])
        return -EINVAL;

    err = nla_parse_nested(tb, TIPC_NLA_MAX, attrs[TIPC_NLA_LINK], NULL);
    if (err < 0)
        return err;

    if (!tb[TIPC_NLA_LINK_DEST] || !tb[TIPC_NLA_LINK_STATUS] ||
