            nla_data(tb[TIPC_NLA_LINK_DEST]));
    nla_put(msg, TIPC_NLA_LINK_STATUS, nla_len(tb[TIPC_NLA_LINK_STATUS]),
            nla_data(tb[TIPC_NLA_LINK_STATUS]));
    nla_put(msg, TIPC_NLA_LINK_NAME, nla_len(tb[TIPC_NLA_LINK_NAME]),
            nla_data(tb[TIPC_NLA_LINK_NAME]));

    return 0;
}

