int tipc_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[TIPC_NL_LINK_ATTR_MAX + 1];
    struct tipc_link_info *info;

    if (!attrs[TIPC_NL_LINK])
        return -EINVAL;

    link_attr = attrs[TIPC_NL_LINK];
    if (nla_parse_nested(tb, TIPC_NL_LINK_ATTR_MAX, link_attr, NULL))
        return -EINVAL;

    if (!tb[TIPC_NL_LINK_ATTR_REMOTE_REF] ||
        !tb[TIPC_NL_LINK_ATTR_STATUS] ||
        !tb[TIPC_NL_LINK_ATTR_NAME])
        return -EINVAL;

    info = kzalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    info->dest = nla_get_u32(tb[TIPC_NL_LINK_ATTR_REMOTE_REF]);
    info->status = nla_get_u32(tb[TIPC_NL_LINK_ATTR_STATUS]);
    nla_strscpy(info->name, tb[TIPC_NL_LINK_ATTR_NAME], TIPC_MAX_LINK_NAME);

    return tipc_nl_compat_msg_add(msg, TIPC_NL_MSG_TYPE_LINK, info,
                                  sizeof(*info));
}

int tipc_nl_compat_dump_link(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *nested;
    int rem;

    if (!attrs[TIPC_NL_COMPAT_ATTR_LINK])
        return -EINVAL;

    link_attr = attrs[TIPC_NL_COMPAT_ATTR_LINK];
    nla_for_each_nested(nested, link_attr, rem) {
        switch (nla_type(nested)) {
        case TIPC_NL_COMPAT_ATTR_LINK_DEST:
            if (nla_len(nested) < sizeof(u32))
                return -EINVAL;
            msg->dest = nla_get_u32(nested);
            break;
        case TIPC_NL_COMPAT_ATTR_LINK_STATUS:
            if (nla_len(nested) < sizeof(u32))
                return -EINVAL;
            msg->status = nla_get_u32(nested);
            break;
        case TIPC_NL_COMPAT_ATTR_LINK_NAME:
            if (nla_len(nested) < sizeof(char))
                return -EINVAL;
            strncpy(msg->name, nla_data(nested), TIPC_MAX_LINK_NAME);
            break;
        default:
            break;
        }
    }

    return 0;
}

int tipc_nl_dump_link_compat(struct tipc_nl_compat_msg *msg, struct nlattr **attrs)
{
    struct nlattr *link_attr;
    struct nlattr *tb[TIPC_NL_LINK_ATTR_MAX + 1];
    int err;

    if (!attrs[TIPC_NL_LINK_ATTR])
        return -EINVAL;

    link_attr = attrs[TIPC_NL_LINK_ATTR];
    err = nla_parse_nested(tb, TIPC_NL_LINK_ATTR_MAX, link_attr, NULL);
    if (err < 0)
        return err;

    if (!tb[TIPC_NL_LINK_ATTR_NAME] || !tb[TIPC_NL_LINK_ATTR_UP] ||
        !tb[TIPC_NL_LINK_ATTR_DEST]) {
        return -EINVAL;
    }

    nla_put_string(msg, TIPC_NL_LINK_ATTR_NAME, nla_data(tb[TIPC_NL_LINK_ATTR_NAME]));
    nla_put_flag(msg, TIPC_NL_LINK_ATTR_UP, nla_get_u8(tb[TIPC_NL_LINK_ATTR_UP]));
    nla_put_u32(msg, TIPC_NL_LINK_ATTR_DEST, nla_get_u32(tb[TIPC_NL_LINK_ATTR_DEST]));

    return 0;
}
